<?php $base = 'operaciones.php?type=' . $page['type']; ?>
<section aria-labelledby="operations-title">
    <div class="contact-toolbar"><div><p class="eyebrow">INVENTARIO · OPERACIONES</p><h1 id="operations-title"><?= inventoryEscape($page['definition']['label']) ?></h1><p class="section-subtitle"><?= $page['total'] ?> registros · Vista de lista</p></div><a class="contact-button contact-button-primary" href="<?= $base ?>&amp;new=1">+ <?= inventoryEscape($page['definition']['new']) ?></a></div>
    <form class="contact-filters" method="get" action="operaciones.php"><input type="hidden" name="type" value="<?= $page['type'] ?>"><label>Buscar<input type="search" name="q" maxlength="160" value="<?= inventoryEscape($page['search']) ?>" placeholder="Referencia o contacto"></label><button class="contact-button" type="submit">Buscar</button><a class="contact-button" href="<?= $base ?>">Limpiar</a></form>
    <div class="contact-table-wrap" role="region" aria-label="Listado de operaciones" tabindex="0"><table class="contact-table"><thead><tr><th scope="col">Referencia</th><th scope="col">Contacto</th><th scope="col">Fecha programada</th><th scope="col">Origen</th><th scope="col">Destino</th><th scope="col">Estado</th></tr></thead><tbody>
        <?php foreach ($page['operations'] as $operation): ?><tr><td><a class="contact-name" href="<?= $base ?>&amp;id=<?= (int) $operation['id'] ?>"><?= inventoryEscape($operation['name']) ?></a></td><td><?= inventoryEscape($operation['contact_name'] ?? '—') ?></td><td><?= inventoryEscape($operation['scheduled_date']) ?></td>
            <td><?= inventoryEscape(storageLabel($page['storage'], inventoryId($operation['source_warehouse_id']), inventoryId($operation['source_location_id'])) ?: ($page['type'] === 'receipt' ? 'Proveedores' : '—')) ?></td>
            <td><?= inventoryEscape(storageLabel($page['storage'], inventoryId($operation['destination_warehouse_id']), inventoryId($operation['destination_location_id'])) ?: ($page['type'] === 'delivery' ? 'Clientes' : '—')) ?></td><td><?= $operation['status'] === 'done' ? 'Realizado' : 'Borrador' ?></td></tr><?php endforeach; ?>
        <?php if (! $page['operations']): ?><tr><td colspan="6" class="contact-empty">No hay operaciones que coincidan con esta búsqueda.</td></tr><?php endif; ?>
    </tbody></table></div>
    <nav class="contact-pagination" aria-label="Páginas de operaciones"><span>Página <?= $page['currentPage'] ?> de <?= $page['pages'] ?></span><?php foreach (['Anterior' => $page['currentPage'] - 1, 'Siguiente' => $page['currentPage'] + 1] as $label => $number): ?><?php if ($number >= 1 && $number <= $page['pages']): ?><a class="contact-button" href="operaciones.php?<?= inventoryEscape(http_build_query(['type' => $page['type'], 'q' => $page['search'], 'page' => $number])) ?>"><?= $label ?></a><?php endif; ?><?php endforeach; ?></nav>
</section>
